async function exportDocumentsPackagesPdf(req, res) {
    try {
        const countryId = req.body.countryId;
        const signers_fields = req.body.signers_fields;

        // Obtiene los tipos de identificación disponibles para el país
        const documentTypes = await db.identification_types.findMany({
            where: {
                country_id: parseInt(countryId),
            },
            select: {
                id: true,
                name: true,
                field_type: true,
            }
        });

        // Separar campos de firma de variables
        const signatureFields = signers_fields.filter(field => 
            field.type === 'signature' || 
            (field.name && field.name.includes('FIRMA'))
        );
        const variableFields = signers_fields.filter(field => field.type === 'variable');

        // Deduplicar firmantes por nombre
        const signers_names = [...new Set(signatureFields.map(field => {
            return field.name.replace(/\[\$|\]/g, '');
        }))];

        const workbook = new ExcelJS.Workbook();
        const worksheet = workbook.addWorksheet('Cargue Masivo');

        // COLUMNAS INICIALES (siempre presentes)
        const columns = [
            { header: 'Fecha límite para realizar la firma', key: 'expires_in_days', width: 30 },
            { header: 'Número de contrato', key: 'contract_number', width: 20 },
        ];

        // COLUMNAS PARA CADA FIRMANTE (basadas en signers_fields)
        signers_names.forEach((field, index) => {
            const match = field.match(/FIRMA(\d+)/);
            const signerNumber = match ? match[1] : '';

            columns.push({ header: `Firmante${signerNumber}_Nombre`, 
                         key: `signer${signerNumber}_name`, width: 15 });
            columns.push({ header: `Firmante${signerNumber}_Apellido`, 
                         key: `signer${signerNumber}_surname`, width: 15 });
            columns.push({ header: `Firmante${signerNumber}_Correo`, 
                         key: `signer${signerNumber}_email`, width: 30 });
            columns.push({ header: `Firmante${signerNumber}_Celular`, 
                         key: `signer${signerNumber}_phone`, width: 20 });
            columns.push({ header: `Firmante${signerNumber}_Tipo_documento`, 
                         key: `signer${signerNumber}_doctype`, width: 30 });
            columns.push({ header: `Firmante${signerNumber}_Documento`, 
                         key: `signer${signerNumber}_document`, width: 20 });
        });

        // COLUMNAS PARA VARIABLES (VAR_)
        // Se procesan campos con type === 'variable' del array signers_fields
        variableFields.forEach((field) => {
            const varName = field.name.replace(/\[\$|\]/g, '');
            // Genera columnas: VAR_{nombre}
            columns.push({ 
                header: `VAR_${varName}`, 
                key: `var_${index}`, 
                width: Math.max(20, (field.exampleText || varName).length + 5)
            });
        });

        worksheet.columns = columns;
        // ... validaciones y formatos de Excel ...
    }
}
